var a=`0556-bahraini-halwa`;var n=`world-0556`;var t=`BH`;var r=`western-asia`;var s=8;var o=108;var h={en:`Bahraini Halwa`,ua:`Бахрейнська халва`};var d={en:`A traditional dish from Bahrain, centered on cornstarch, pistachio. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Бахрейн. Основні складники: кукурудзяний крохмаль, фісташка. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Warm sugar and water until the sugar dissolves, keeping the syrup clear for the halwa.`,ua:`Прогрівайте цукор із водою до розчинення, зберігаючи прозорий сироп для халви.`,t:[`caramelizing-sugar`],m:13,i:[[`white-granulated-sugar`,280,`g`],[`water`,230,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`cornstarch`,100,`g`],[`rose-water`,25,`ml`],[`saffron-threads`,.25,`g`],[`ground-cardamom`,5,`g`],[`unsalted-butter`,65,`g`]]},{en:`Stir the rose-scented starch syrup continuously over low heat until smooth, translucent and very thick; pour into a greased dish to cool.`,ua:`Постійно помішуйте крохмальний сироп із трояндовою водою на малому вогні до гладкої густої напівпрозорої маси; перелийте у змащену форму для охолодження.`,t:[`slow-simmer-reduction`],m:80,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pistachio`,70,`g`]]}];var l={slug:a,id:n,country:`BH`,region:r,servings:8,minutes:108,title:h,text:d,steps:g};export{t as country,l as default,n as id,o as minutes,r as region,s as servings,a as slug,g as steps,d as text,h as title};